import math
def interp(points, u):
    pts=sorted(points, key=lambda p:p[0])
    if not pts: return None
    if u <= pts[0][0]: return pts[0][1]
    for (u0,v0),(u1,v1) in zip(pts,pts[1:]):
        if u0 <= u <= u1:
            f=(u-u0)/(u1-u0) if u1!=u0 else 0
            return v0+f*(v1-v0)
    return pts[-1][1]
def control(obs):
    view=obs.get('view',{})
    # Visibility is maintained facing straight back; use paired rail samples to estimate the course centre.
    left=view.get('left_rail',[])
    right=view.get('right_rail',[])
    centers=[]
    for u in (2.5,4.5,6.5,8.5,10.5):
        a=interp(left,u); b=interp(right,u)
        if a is not None and b is not None: centers.append((u,(a+b)/2))
    if centers:
        u,v=centers[min(1,len(centers)-1)]
        farther=centers[-1]
        angle=math.atan2(farther[1]-v,max(0.1,farther[0]-u))
        # Positive steer sends the trailer rear toward its left while reversing.
        steer=max(-18,min(18, math.degrees(angle)*1.25))
    else: steer=0
    hitch=obs.get('hitch_deg',0)
    steer += max(-8,min(8, hitch*0.35))
    steer=max(-22,min(22,steer))
    return (steer,-0.8,180)

