import math
def interp(points,u):
    pts=sorted(points,key=lambda p:p[0])
    if not pts:return None
    if u<=pts[0][0]:return pts[0][1]
    for (u0,v0),(u1,v1) in zip(pts,pts[1:]):
        if u0<=u<=u1:
            f=(u-u0)/(u1-u0) if u1!=u0 else 0.0
            return v0+f*(v1-v0)
    return pts[-1][1]
def control(obs):
    view=obs.get('view',{})
    left=view.get('left_rail',[])
    right=view.get('right_rail',[])
    vals=[]
    for u in (2.0,3.5,5.0):
        a=interp(left,u); b=interp(right,u)
        if a is not None and b is not None: vals.append((u,(a+b)*0.5))
    steer=0.0
    if len(vals)>=2:
        # Follow the course centre in the lookahead direction; positive steer moves the reversing trailer rear right.
        u,v=vals[min(1,len(vals)-1)]
        slope=(vals[-1][1]-vals[0][1])/max(0.5,vals[-1][0]-vals[0][0])
        steer=max(-24.0,min(24.0,-math.degrees(math.atan(slope))*0.95 - v*3.0))
    h=obs.get('hitch_deg',0.0)
    steer=max(-25.0,min(25.0,steer+max(-9.0,min(9.0,1.0*h))))
    return (steer,-0.42,180)

