def control(obs):
    view = obs.get('view', {})
    # Estimate the rail midpoint ahead of the trailer rear from currently visible points.
    left = obs.get('local_map', {}).get('left_rail', []) or []
    right = obs.get('local_map', {}).get('right_rail', []) or []
    if not left and not right:
        left = view.get('left_rail', []) or []
        right = view.get('right_rail', []) or []
    pairs = []
    for p in left:
        if len(p) >= 2 and 3.0 <= p[0] <= 9.0:
            near = min(right, key=lambda q: abs(q[0]-p[0])) if right else None
            if near and abs(near[0]-p[0]) < 0.7:
                pairs.append((p[0], (p[1]+near[1])*0.5))
    center = sum(v for u,v in pairs)/len(pairs) if pairs else 0.0
    hitch = obs.get('hitch_deg', 0.0)
    # Positive steer corrects positive hitch; negative steer sends trailer rear left.
    steer = 0.85*hitch - 1.8*center
    steer = max(-25.0, min(25.0, steer))
    return (steer, -0.8, 180)

