import math
def control(obs):
    m=obs.get('local_map',{})
    L=m.get('left_rail',[])
    R=m.get('right_rail',[])
    def interp(points,u):
        pts=sorted(points,key=lambda p:p[0])
        if len(pts)<2: return None
        for a,b in zip(pts,pts[1:]):
            if a[0]<=u<=b[0]:
                f=(u-a[0])/(b[0]-a[0] or 1e-9)
                return a[1]+f*(b[1]-a[1])
        return min(pts,key=lambda p:abs(p[0]-u))[1]
    vals=[]
    for u in (1.5,2.5,3.5,4.5):
        l,r=interp(L,u),interp(R,u)
        if l is not None and r is not None: vals.append((u,(l+r)/2))
    h=math.radians(obs.get('hitch_deg',0))
    if vals:
        weights=[1/(u+1.0) for u,v in vals]
        aim=sum(v*w for (u,v),w in zip(vals,weights))/sum(weights)
        steer=-22.0*aim-48.0*h
    else: steer=-48.0*h
    steer=max(-28.0,min(28.0,steer))
    return (steer,-0.38,180)

