import math
def interp(points,u):
    pts=sorted(points,key=lambda p:p[0])
    if len(pts)<2: return None
    for a,b in zip(pts,pts[1:]):
        if a[0]<=u<=b[0]:
            f=(u-a[0])/(b[0]-a[0] or 1e-9)
            return a[1]+f*(b[1]-a[1])
    return min(pts,key=lambda p:abs(p[0]-u))[1]
def control(obs):
    m=obs.get('local_map',{})
    L=m.get('left_rail',[]); R=m.get('right_rail',[])
    vals=[]
    for u in (0.8,1.5,2.2):
        l=interp(L,u); r=interp(R,u)
        if l is not None and r is not None: vals.append((u,(l+r)*0.5))
    if vals:
        aim=sum(v/(u+0.5) for u,v in vals)/sum(1/(u+0.5) for u,v in vals)
    else: aim=0.0
    h=float(obs.get('hitch_deg',0.0))
    steer=max(-12.0,min(12.0,5.0*aim+0.22*h))
    return (steer,-0.16,180)

