import math
phase = 'recover'
def control(obs):
    global phase
    h = float(obs.get('hitch_deg', 0.0))
    m = obs.get('local_map', {})
    L, R = m.get('left_rail', []), m.get('right_rail', [])
    def at(pts, u):
        pts = sorted(pts, key=lambda p: p[0])
        for a, b in zip(pts, pts[1:]):
            if a[0] <= u <= b[0]:
                f = (u-a[0])/(b[0]-a[0] or 1e-9)
                return a[1] + f*(b[1]-a[1])
        return None
    centers = []
    for u in (0.2, 0.45, 0.7):
        l, r = at(L,u), at(R,u)
        if l is not None and r is not None:
            centers.append((l+r)*0.5)
    center = sum(centers)/len(centers) if centers else -0.8
    if phase == 'recover':
        if abs(h) > 3.0:
            return (24.0 if h > 0 else -24.0, 0.16, 180)
        phase = 'reverse'
    steer = max(-8.0, min(8.0, -2.2*center + 0.22*h))
    return (steer, -0.08, 180)

